  workerWorkCounts(){return{datasetOperations:Number(this.database.prepare("SELECT COUNT(*) AS n FROM dataset_operations WHERE status='leased'").get().n),processing:Number(this.database.prepare("SELECT COUNT(*) AS n FROM processing_jobs WHERE status='leased'").get().n),derivatives:Number(this.database.prepare("SELECT COUNT(*) AS n FROM derivative_jobs WHERE status='leased'").get().n),events:Number(this.database.prepare("SELECT COUNT(*) AS n FROM event_outbox WHERE status='leased'").get().n)};}

  createAdminGrant({subject,permissions,displayUnits,expiresAt,authorizationExpiresAt}) { const id=crypto.randomUUID(),token=crypto.randomBytes(32).toString('base64url'),t=now(); this.database.prepare('INSERT INTO admin_grants(id,token_hash,subject,permissions_json,display_units,expires_at,authorization_expires_at,created_at) VALUES (?,?,?,?,?,?,?,?)').run(id,crypto.createHash('sha256').update(token).digest('hex'),bounded(subject,200),JSON.stringify(permissions||[]),displayUnits||'imperial',expiresAt,authorizationExpiresAt,t); return {token,subject,permissions,displayUnits:displayUnits||'imperial',expiresAt,authorizationExpiresAt,createdAt:t}; }
  redeemAdminGrant(token,at=Date.now()) { const hash=crypto.createHash('sha256').update(token||'').digest('hex');return this.transaction(()=>{ const row=this.database.prepare('SELECT * FROM admin_grants WHERE token_hash=?').get(hash);if(!row||row.redeemed_at||Date.parse(row.expires_at)<=at||Date.parse(row.authorization_expires_at)<=at)return null;const t=new Date(at).toISOString();const changed=this.database.prepare('UPDATE admin_grants SET redeemed_at=? WHERE id=? AND redeemed_at IS NULL').run(t,row.id);return changed.changes===1?{id:row.id,subject:row.subject,permissions:json(row.permissions_json,[]),displayUnits:row.display_units,expiresAt:row.expires_at,authorizationExpiresAt:row.authorization_expires_at}:null; }); }
  adminSession(row) { return row&&{id:row.id,tokenHash:row.token_hash,subject:row.subject,permissions:json(row.permissions_json,[]),displayUnits:row.display_units,expiresAt:row.expires_at,revokedAt:row.revoked_at,createdAt:row.created_at,updatedAt:row.updated_at}; }
  createAdminSession({tokenHash,subject,permissions,displayUnits,expiresAt}) { const id=crypto.randomUUID(),t=now();this.database.prepare('INSERT INTO admin_sessions(id,token_hash,subject,permissions_json,display_units,expires_at,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?)').run(id,tokenHash,subject,JSON.stringify(permissions),displayUnits||'imperial',expiresAt,t,t);return this.getAdminSessionByHash(tokenHash); }
  getAdminSessionByHash(hash) { return this.adminSession(this.database.prepare('SELECT * FROM admin_sessions WHERE token_hash=?').get(hash)); }
  adminSessionLive(session,at=Date.now()) { return Boolean(session&&!session.revokedAt&&Date.parse(session.expiresAt)>at); }
  renewAdminSession(id,{permissions,displayUnits,expiresAt}) { const t=now();const changed=this.database.prepare('UPDATE admin_sessions SET permissions_json=?,display_units=?,expires_at=?,updated_at=? WHERE id=? AND revoked_at IS NULL').run(JSON.stringify(permissions),displayUnits||'imperial',expiresAt,t,id);return changed.changes===1?this.adminSession(this.database.prepare('SELECT * FROM admin_sessions WHERE id=?').get(id)):null; }
