  getSubjectOperationReceipt(subject,key){const row=this.database.prepare('SELECT * FROM subject_operation_receipts WHERE subject=? AND client_key=?').get(subject,key);return row&&{subject:row.subject,key:row.client_key,method:row.method,path:row.path,requestHash:row.request_sha256,responseStatus:row.response_status,response:json(row.response_json,null),operationId:row.operation_id,createdAt:row.created_at,updatedAt:row.updated_at};}
  pruneSubjectOperationReceipts(retentionDays=7,at=Date.now()){return this.transaction(()=>{const cutoff=new Date(at-Math.max(1,Number(retentionDays)||7)*86400_000).toISOString();const redacted=this.database.prepare('UPDATE subject_operation_receipts SET response_status=NULL,response_json=NULL,updated_at=? WHERE operation_id IS NOT NULL AND response_json IS NOT NULL AND created_at<?').run(now(),cutoff).changes;const removed=this.database.prepare('DELETE FROM subject_operation_receipts WHERE operation_id IS NULL AND response_status IS NOT NULL AND created_at<?').run(cutoff).changes;return{redacted,removed};});}

  createImportPreview({request,preview,createdBy,createdSessionId,expiresAt}) { const id=crypto.randomUUID(),token=crypto.randomBytes(32).toString('base64url'),t=now();this.database.prepare('INSERT INTO dataset_import_previews(id,token_hash,request_json,preview_json,expires_at,created_by,created_session_id,created_at) VALUES (?,?,?,?,?,?,?,?)').run(id,crypto.createHash('sha256').update(token).digest('hex'),JSON.stringify(request),JSON.stringify(preview),expiresAt,createdBy,createdSessionId||null,t);return{id,token,preview,expiresAt}; }
