  datasetOperation(row){if(!row)return null;const payload=json(row.payload_json,{}),request=payload.request||{},type=payload.webodmTaskImport?'webodm_task_import':row.operation_type,progress=Number(row.progress)||0,status=row.status;let source=null,phase=status;if(type==='upload_finalize'){source={kind:'browser_upload',browserTransferRequired:true,transferComplete:true};if(row.status==='leased')phase='assembling_upload';}else if(type==='webodm_task_import'){const kind=payload.importSource?.kind||(/\.zip$/i.test(String(request.sourceRelativePath||''))?'server_zip':'server_folder');source={kind,browserTransferRequired:false,transferComplete:true};if(row.status==='awaiting_derivatives')phase='awaiting_derivatives';else if(row.status==='leased')phase=progress<0.25?(kind==='server_zip'?'extracting':'staging'):progress<0.35?'discovering':progress<0.7?'adopting':'registering';}else if(['import_preview','import_adopt'].includes(type)){source={kind:'server_mount',browserTransferRequired:false,transferComplete:true};if(row.status==='leased')phase=type==='import_preview'?'inspecting':'adopting';}return{id:row.id,type,subject:row.subject,projectId:request.projectId||null,datasetId:row.dataset_id,uploadId:row.upload_id,processingAttemptId:row.processing_attempt_id||null,status,phase,progress,result:json(row.result_json,null),errorCode:row.error_code,errorMessage:row.error_message,source,attemptCount:Number(row.attempt_count)||0,heartbeatAt:row.heartbeat_at||null,createdAt:row.created_at,updatedAt:row.updated_at,completedAt:row.completed_at};}
  getDatasetOperation(id,subject=null){const row=subject?this.database.prepare('SELECT * FROM dataset_operations WHERE id=? AND subject=?').get(id,subject):this.database.prepare('SELECT * FROM dataset_operations WHERE id=?').get(id);return this.datasetOperation(row);}
  listDatasetOperationsPage({subject,status=null,projectId=null,limit=50,cursor=null}={}){if(!subject)throw Object.assign(new Error('operation subject is required'),{code:'invalid_subject'});if(status&&!['queued','leased','awaiting_derivatives','succeeded','failed','cancelled'].includes(status))throw Object.assign(new Error('invalid operation status'),{code:'invalid_status'});const n=pageLimit(limit),c=decodeCursor(cursor),where=['subject=?'],args=[subject];if(status){where.push('status=?');args.push(status);}if(projectId){where.push("(json_extract(payload_json,'$.request.projectId')=? OR dataset_id IN (SELECT id FROM datasets WHERE project_id=?))");args.push(projectId,projectId);}if(c){where.push('(created_at<? OR (created_at=? AND id<?))');args.push(c.createdAt,c.createdAt,c.id);}const rows=this.database.prepare(`SELECT * FROM dataset_operations WHERE ${where.join(' AND ')} ORDER BY created_at DESC,id DESC LIMIT ?`).all(...args,n+1),items=rows.slice(0,n);return{items:items.map((row)=>this.datasetOperation(row)),nextCursor:rows.length>n?encodeCursor(items.at(-1)):null};}
  createImportPreviewOperation({request,subject,sessionId,receipt=null,auditActorId=null}){return this.transaction(()=>{const t=now(),id=crypto.randomUUID();this.database.prepare("INSERT INTO dataset_operations(id,operation_type,subject,session_id,payload_json,status,available_at,created_at,updated_at) VALUES (?,'import_preview',?,?,?,'queued',?,?,?)").run(id,subject,sessionId||null,JSON.stringify(request),t,t,t);this.attachSubjectOperationReceipt(receipt,id);if(auditActorId)this.insertAudit({actorId:auditActorId,action:'dataset_operation.import_preview_enqueued',entityType:'dataset_operation',entityId:id,details:{operationType:'import_preview'}});return this.getDatasetOperation(id);});}
  createWebodmTaskImportOperation({request,subject,sessionId,receipt=null,auditActorId=null}){return this.transaction(()=>{const project=this.getProject(request.projectId);if(!project||project.status!=='active')return null;const t=now(),id=crypto.randomUUID(),ids={datasetId:crypto.randomUUID(),taskId:crypto.randomUUID(),attemptId:crypto.randomUUID(),modelId:crypto.randomUUID(),versionId:crypto.randomUUID()},importSource={kind:/\.zip$/i.test(String(request.sourceRelativePath||''))?'server_zip':'server_folder'};const payload={webodmTaskImport:true,importSource,request,ids};this.database.prepare("INSERT INTO dataset_operations(id,operation_type,subject,session_id,payload_json,status,available_at,created_at,updated_at) VALUES (?,'catalog_map',?,?,?,'queued',?,?,?)").run(id,subject,sessionId||null,JSON.stringify(payload),t,t,t);this.attachSubjectOperationReceipt(receipt,id);if(auditActorId)this.insertAudit({actorId:auditActorId,action:'webodm_task_import.queued',entityType:'dataset_operation',entityId:id,details:{operationType:'webodm_task_import',projectId:request.projectId,sourceKind:importSource.kind}});return this.getDatasetOperation(id);});}
  webodmTaskImport(row){return row&&{id:row.id,sourceFingerprint:row.source_fingerprint,sourceRelativePath:row.source_relative_path,projectId:row.project_id,taskId:row.task_id,datasetId:row.dataset_id,attemptId:row.attempt_id,modelId:row.model_id,modelVersionId:row.model_version_id,assetKinds:json(row.asset_kinds_json,[]),createdBy:row.created_by,createdAt:row.created_at};}
